//! Owner-token handling.
//!
//! The token is generated by the client and is the only credential a goal owner
//! has, so the server never stores it: it stores `sha256(token)` and compares that
//! digest in constant time. A database leak therefore does not hand anyone the
//! ability to post thanks, close jars, or impersonate an owner.

use sha2::{Digest, Sha256};
use subtle::ConstantTimeEq;

pub fn hash_token(token: &str) -> String {
    hex::encode(Sha256::digest(token.as_bytes()))
}

/// Constant-time comparison of a presented token against a stored digest.
pub fn token_matches(presented: &str, stored_hash: &str) -> bool {
    let candidate = hash_token(presented.trim());
    // `ct_eq` refuses to short-circuit on the first differing byte.
    candidate
        .as_bytes()
        .ct_eq(stored_hash.as_bytes())
        .into()
}

pub fn extract_bearer(headers: &axum::http::HeaderMap) -> Option<String> {
    headers
        .get("x-owner-token")
        .and_then(|value| value.to_str().ok())
        .map(|value| value.trim().to_string())
        .filter(|value| !value.is_empty())
}

#[cfg(test)]
mod tests {
    use super::*;

    const TOKEN: &str = "9f2c1b6d0a7e4c3b8d5f1a2e6c9b0d3f7a4e8c1b5d2f9a6c3b0e7d4f1a8c5b2e";

    #[test]
    fn hashing_is_stable_and_hex() {
        assert_eq!(hash_token(TOKEN).len(), 64);
        assert_eq!(hash_token(TOKEN), hash_token(TOKEN));
        assert_ne!(hash_token(TOKEN), hash_token("deadbeef"));
    }

    #[test]
    fn matches_only_the_right_token() {
        let stored = hash_token(TOKEN);
        assert!(token_matches(TOKEN, &stored));
        assert!(!token_matches("", &stored));
        assert!(!token_matches(&TOKEN[..63], &stored));
        assert!(!token_matches(TOKEN, &hash_token("something-else")));
    }
}
